:root {
  /* Colors */
  --color-paper-canvas: #fdfdfd;
  --color-fog-surface: #f9f9f9;
  --color-quartz-white: #ffffff;
  --color-ink: #030303;
  --color-graphite-caption: #525252;
  --color-ash-caption: #a0a0a0;
  --color-pebble-border: #d8d8d8;
  --color-onyx-dot: #000000;
  --color-forest-signal: #0e7e4e;
  --color-mint-pulse: #3fcf8e;
  --color-moss-syntax: #15593b;
  --color-iris-syntax: #6b35dc;
  --color-ember-syntax: #b45309;

  /* Typography — Font Families */
  --font-manrope: "Manrope", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-source-code-pro: "Source Code Pro", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.33;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.7;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 15px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 16px;
  --leading-subheading: 1.5;
  --tracking-subheading: 0px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.33;
  --tracking-heading-sm: -0.16px;
  --text-heading: 34px;
  --leading-heading: 1.11;
  --tracking-heading: 0px;
  --text-display: 46px;
  --leading-display: 1.0;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 450;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-128: 128px;
  --spacing-160: 160px;

  /* Layout */
  --page-max-width: 1280px;
  --section-gap: 96px;
  --card-padding: 24px;
  --element-gap: 8px;

  /* Border Radius */
  --radius-sm: 5px;
  --radius-md: 8px;
  --radius-md-2: 9px;
  --radius-lg: 11px;
  --radius-xl: 16px;
  --radius-2xl: 21px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 21px;
  --radius-small-cards: 16px;
  --radius-inner-tiles: 11px;
  --radius-buttons: 9px;
  --radius-nav: 8px;
  --radius-inputs: 8px;
  --radius-small-elements: 5px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0 1px 3px 0 rgba(0,0,0,0.04), inset 0 1px 0 0 rgba(0,0,0,0.027), inset 0 0 0 1px rgba(0,0,0,0.04), inset 0 -1px 0 0 rgba(0,0,0,0.04), inset 0 0 0 1px rgba(0,0,0,0.067);
  --shadow-subtle-2: 0 1px 3px 0 rgba(0,0,0,0.04), inset 0 1px 0 0 rgba(0,0,0,0.027), inset 0 0 0 1px rgba(0,0,0,0.04), inset 0 0 0 1px rgba(0,0,0,0.067);
  --shadow-sm: inset 0 0 0 1px rgba(255,255,255,0.12);
  --shadow-sm-2: 0 0 0 1px rgba(255,255,255,0.3);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);

  /* Surfaces */
  --surface-paper-canvas: #fdfdfd;
  --surface-fog-surface: #f9f9f9;
  --surface-quartz-white: #ffffff;
  --surface-onyx-dot: #000000;
}

